const raw =
  $json.content?.parts?.[0]?.text ??
  $json.text ??
  $json;

let parsed = raw;

if (typeof raw === 'string') {
  const cleaned = raw
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();

  parsed = JSON.parse(cleaned);
}

const territories = parsed.creative_territories || [];

if (!Array.isArray(territories) || territories.length === 0) {
  throw new Error('No creative territories found in Gemini output');
}

// Get the original product image URL from the HTML extraction node
const ogImage = $('Extract Product Page').first().json.og_image;

if (!ogImage) {
  throw new Error('og_image not found in Extract Product Page');
}

// Create one n8n item per creative territory
return territories.map((territory, index) => ({
  json: {
    creative_index: index + 1,
    creative_id: `ANGLE_${String(index + 1).padStart(2, '0')}`,
    og_image: ogImage,
    ...territory
  }
}));
